vec2 v0 = points[2] - points[0];
vec2 v1 = points[1] - points[0];
float dot00 = v0.x * v0.x + v0.y * v0.y;
float dot01 = v0.x * v1.x + v0.y * v1.y;
float dot11 = v1.x * v1.x + v1.y * v1.y;
float inv_denom = 1 / (dot00 * dot11 - dot01 * dot01);
float u = (dot11 * v0.x - dot01 * v1.x) * inv_denom;
float v = (dot00 * v1.x - dot01 * v0.x) * inv_denom;
return (u + v) >= 1.0f;

